[CmdletBinding()] param()
$ErrorActionPreference="Stop";$baselineDirectory=$PSScriptRoot;$projectRoot=Split-Path -Parent (Split-Path -Parent $baselineDirectory);$docker="C:\Program Files\Docker\Docker\resources\bin\docker.exe";$container="akis-metadata-db-1";$db="akis_release_test_"+[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds();$created=$false
$settings=@{};Get-Content (Join-Path $projectRoot '.env')|Where-Object{$_ -match '^[A-Za-z_][A-Za-z0-9_]*='}|ForEach-Object{$n,$v=$_ -split '=',2;$settings[$n]=$v};$u=(&$docker exec $container sh -lc 'printf %s "$POSTGRES_USER"').Trim()
try{&$docker exec $container createdb -U $u $db;if($LASTEXITCODE){throw 'create failed'};$created=$true;foreach($name in @('V001__identity_rbac_project.sql','V002__connections_and_schemas.sql','V003__folders_definitions_and_versions.sql','V004__catalog_and_schema_snapshots.sql','V005__validation_and_scenarios.sql','V006__runnable_releases_and_approvals.sql','verify-releases.sql')){$path=Join-Path $baselineDirectory $name;&$docker cp $path "${container}:/tmp/$name"|Out-Null;&$docker exec $container psql -v ON_ERROR_STOP=1 -U $u -d $db -f "/tmp/$name";if($LASTEXITCODE){throw $name}};$env:SPRING_DATASOURCE_URL="jdbc:postgresql://localhost:$($settings['POSTGRES_PORT'])/$db";$env:SPRING_DATASOURCE_USERNAME=$u;$env:SPRING_DATASOURCE_PASSWORD=$settings['POSTGRES_PASSWORD'];&(Join-Path $projectRoot 'mvnw.cmd') -pl backend '-Dtest=CleanPublicationRepositoryIT' test;if($LASTEXITCODE){throw 'repository test failed'};'Clean runnable release and approval repository tests: PASS'}finally{if($created -and $db -match '^akis_release_test_[0-9]+$'){&$docker exec $container dropdb --if-exists --force -U $u $db|Out-Null}}
